package nettrace

import (
	"errors"
	"syscall"
)

// IsNoRoute reports whether err means "this machine has no route to the
// target": ErrNoRoute, or a raw network/host unreachable errno anywhere in the
// chain. The error text alone never counts. It is the single place that
// classifies a no-route failure.
func IsNoRoute(err error) bool {
	return errors.Is(err, ErrNoRoute) ||
		errors.Is(err, syscall.ENETUNREACH) ||
		errors.Is(err, syscall.EHOSTUNREACH)
}
package nettrace

import (
	"errors"
	"fmt"
	"syscall"
	"testing"
)

func TestIsNoRoute(t *testing.T) {
	tests := []struct {
		name string
		err  error
		want bool
	}{
		{"nil", nil, false},
		{"ErrNoRoute", ErrNoRoute, true},
		{"wrapped ErrNoRoute", fmt.Errorf("trace: %w", ErrNoRoute), true},
		{"wrapped ENETUNREACH", fmt.Errorf("netlink error: %w", syscall.ENETUNREACH), true},
		{"wrapped EHOSTUNREACH", fmt.Errorf("connect: %w", syscall.EHOSTUNREACH), true},
		{"ECONNREFUSED", syscall.ECONNREFUSED, false},
		{"EACCES", syscall.EACCES, false},
		// Text alone is unknown, not "no route".
		{"text only", errors.New("no route found for x"), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := IsNoRoute(tt.err); got != tt.want {
				t.Errorf("IsNoRoute(%v) = %v, want %v", tt.err, got, tt.want)
			}
		})
	}
